-- Permanently categorize all skills into standardized professional domains

-- Category: Software & Web Development
UPDATE skills SET category = 'Software & Web Development' WHERE normalized_name IN ('.net', '.net core', 'angular', 'apex', 'api gateway', 'architecture', 'c', 'c#', 'c++', 'clean architecture', 'css3', 'cucumber', 'cypress', 'django', 'fastapi', 'graphql', 'hibernate', 'html/css', 'html5', 'java', 'javascript', 'jest', 'junit', 'lightning web components', 'node.js', 'performance tuning', 'php', 'playwright', 'postman', 'quality assurance', 'react', 'redux', 'rest apis', 'rxjs', 'sap erp', 'selenium', 'sonarqube', 'spring boot', 'spring cloud', 'static analysis', 'tailwind css', 'test automation', 'testing', 'testng', 'typescript', 'uat testing', 'unit testing', 'ux design');

